from solution import search


def test_issue_example_from_prompt():
    """Example: search([1,1,2,2,3],5) == 3."""
    assert search([1, 1, 2, 2, 3], 5) == 3  # 5//2=2 pairs + singleton 3


def test_issue_singleton_at_start():
    """Find the element that appears only once when it is first."""
    assert search([1, 2, 2, 3, 3], 5) == 1  # 5//2=2 pairs + singleton 1; 0+1=1


def test_issue_singleton_in_middle():
    """Find the element that appears only once when it is in the middle."""
    assert search([1, 1, 2, 3, 3], 5) == 2  # 5//2=2 pairs + singleton 2; 1+1=2


def test_issue_single_element_array():
    """Find the element that appears only once in a single-element array."""
    assert search([7], 1) == 7  # 1//2=0 pairs + singleton 7; 6+1=7


def test_issue_three_elements_unique_at_end():
    """Find the element that appears only once with minimal pairs."""
    assert search([1, 1, 2], 3) == 2  # 3//2=1 pair + singleton 2; 1+1=2


def test_issue_singleton_middle_longer():
    """Find the element that appears only once in a longer middle case."""
    assert search([1, 1, 2, 2, 3, 4, 4], 7) == 3  # 7//2=3 pairs + singleton 3; 1+2=3


def test_issue_singleton_at_end_longer():
    """Find the element that appears only once when it is last in longer array."""
    assert search([1, 1, 2, 2, 3, 3, 4], 7) == 4  # 7//2=3 pairs + singleton 4; 3+1=4


def test_issue_negative_sorted():
    """Find the element that appears only once with negative numbers."""
    assert search([-3, -3, -2, -1, -1], 5) == -2  # 5//2=2 pairs + singleton -2; -3+1=-2


def test_contract_value_not_index():
    """Returns element value that appears once, not its index."""
    assert search([5, 5, 6, 7, 7], 5) == 6  # 5//2=2 pairs, value 6 != index 2; 5+1=6


def test_contract_zero_boundary():
    """Find the element that appears only once with zero boundary."""
    assert search([0, 0, 1, 1, 2], 5) == 2  # 5//2=2 pairs + singleton 2; 1+1=2


def test_contract_large_sorted_values():
    """Find the element that appears only once among larger values."""
    assert search([10, 10, 20, 20, 30], 5) == 30  # 5//2=2 pairs + singleton 30; 20+10=30
